require_once __DIR__.'/../bootstrap.php';requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST')fail('Método no permitido.',405);$d=jsonBody();$n=requiredText($d,'nombre',100);$dir=requiredText($d,'direccion',180);$emp=filter_var($d['empleados']??null,FILTER_VALIDATE_INT);if($emp===false||$emp===null||$emp<0||$emp>65535)fail('La cantidad de empleados debe ser un entero entre 0 y 65535.',422);$st=db()->prepare('INSERT INTO sucursales(nombre,direccion,empleados) VALUES(?,?,?)');$st->execute([$n,$dir,$emp]);respond(['id'=>(int)db()->lastInsertId(),'nombre'=>$n,'direccion'=>$dir,'empleados'=>$emp],201);
